13	/// Drives `ChatScreen` — a DI `lazySingleton` (Code Map, mirroring
14	/// `MeusRegistrosCubit`): long-lived, so returning to Home/Chat within the
15	/// same app session never re-bootstraps the session/history it already
16	/// loaded (`init()`'s own no-op guard below).
17	class ChatCubit extends Cubit<ChatState> {
18	  ChatCubit(this._repository) : super(const ChatBootstrapLoading());
19	
20	  final ChatRepository _repository;
21	
22	  StreamSubscription<Either<Failure, ChatStreamEvent>>? _sendSubscription;
23	
24	  /// The in-flight [sendMessage]'s own completer, if any — [close] must
25	  /// complete it itself, since cancelling [_sendSubscription] never fires
26	  /// `onDone`/`onError` (review fix: `cancel()` alone left `sendMessage()`'s
27	  /// returned `Future` permanently unresolved when the cubit closed mid-send).
28	  Completer<void>? _sendCompleter;
