30	  /// Monotonic counter behind every locally generated [ChatUiMessage.id]
31	  /// (Code Map) — never the server's own message id (see `ChatStreamEvent`'s
32	  /// own doc on why `message_created`'s id goes unused here).
33	  int _localIdCounter = 0;
34	
35	  /// Whether a send is actively in flight right now — tracked locally
36	  /// rather than by scanning [ChatState.messages] for a persisted
37	  /// `streaming` status, since a message loaded from history/cache can
38	  /// legitimately carry that same status (e.g. one left over from an
39	  /// earlier dropped response, the I/O matrix's own scenario) without a
40	  /// send actually being in progress; scanning for it would permanently
41	  /// disable the composer in that case.
42	  bool _isSending = false;
43	
44	  /// An in-flight bootstrap, if any — reused by a concurrent `init()` call
45	  /// instead of starting a second bootstrap, so two near-simultaneous
46	  /// callers (e.g. two mounts before the first resolves) never both
47	  /// observe "no sessions" and both call `createSession()` (Boundaries:
48	  /// "silently ensure *one* Chat Session exists").
49	  Future<void>? _initFuture;
50	
51	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
52	  /// `sessionId`, on `ChatCubit` (never Hive) — survives session switches
53	  /// within one app run, resets on restart." Lives on this long-lived
54	  /// `lazySingleton` cubit itself (Design Notes), never on [ChatReady] —
55	  /// a state value would otherwise have to be threaded through every
56	  /// unrelated `copyWith` call just to avoid losing it.
57	  final Map<String, double> _scrollOffsets = {};
58	
59	  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
60	  /// exists (reuse the most recent from `chat-sessions-list`, else
61	  /// `chat-sessions-create` with no title)". A no-op once already
62	  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
63	  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
64	  /// from an earlier visit.
65	  Future<void> init() {
66	    if (state is ChatReady || isClosed) {
67	      return Future.value();
68	    }
69	    return _initFuture ??= _bootstrap().whenComplete(() => _initFuture = null);
70	  }
71	
72	  Future<void> _bootstrap() async {
73	    emit(const ChatBootstrapLoading());
74	
75	    final sessionsResult = await _repository.listSessions();
76	    if (isClosed) {
77	      return;
78	    }
79	    // Captured by the closures below so the resulting [ChatReady] can
80	    // carry every known session (Code Map: "capture resolved sessions
81	    // into the emitted ChatReady"), not just the one picked to reuse.
82	    List<ChatSession> sessions = const [];
83	    final Either<Failure, ChatSession> sessionResult = await sessionsResult
84	        .match((failure) async => left(failure), (fetchedSessions) async {
85	          if (fetchedSessions.isEmpty) {
86	            final createResult = await _repository.createSession();
87	            return createResult.match((failure) => left(failure), (session) {
88	              sessions = [session];
89	              return right(session);
90	            });
91	          }
92	          sessions = fetchedSessions;
93	          // "reuse the most recent" — defensively re-sorts rather than
94	          // trusting `listSessions()`'s own ordering (its offline-cache
95	          // fallback already sorts `updatedAt` desc, but the live
96	          // server response's own ordering isn't documented either
97	          // way). `tryParse` (never `parse`) — same crash-safe pattern as
98	          // `AppDrawer`'s own session sort (review finding "Crash risk in
99	          // the new `_ConversasSection` sort"): a malformed `updatedAt`
100	          // must never crash bootstrap itself, so it falls back to the
101	          // epoch and simply sorts last instead of throwing.
102	          final mostRecent = [...fetchedSessions]..sort(
103	            (a, b) => (DateTime.tryParse(b.updatedAt) ?? DateTime(0))
104	                .compareTo(DateTime.tryParse(a.updatedAt) ?? DateTime(0)),
105	          );
106	          return right(mostRecent.first);
107	        });
108	    if (isClosed) {
109	      return;
110	    }
111	
112	    await sessionResult.match(
113	      (failure) async {
114	        if (!isClosed) {
115	          emit(ChatBootstrapError(failure));
116	        }
117	      },
118	      (session) async {
119	        final messagesResult = await _repository.listMessages(session.id);
120	        if (isClosed) {
121	          return;
122	        }
123	        messagesResult.match(
124	          (failure) => emit(ChatBootstrapError(failure)),
125	          (messages) => emit(
126	            ChatReady(
127	              sessionId: session.id,
128	              messages: messages.map(_fromDomain).toList(),
129	              sessions: sessions,
130	            ),
131	          ),
132	        );
133	      },
134	    );
135	  }
136	
137	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
138	  /// `sessionId`" — `ChatScreen`'s own `ScrollController` listener calls
139	  /// this on every scroll update, so whichever offset a session was last
140	  /// left at is always the one [switchSession] hands back when that
141	  /// session becomes active again.
142	  void recordScrollOffset(String sessionId, double offset) {
143	    _scrollOffsets[sessionId] = offset;
144	  }
145	
146	  /// I/O matrix: "Switch session"/"Switch to already-active session" —
147	  /// a no-op [Right] when [sessionId] is already [ChatReady.sessionId]
148	  /// (the drawer still closes, nothing reloads/re-fetches); otherwise
149	  /// fetches that session's own history via `listMessages` (reused as-is,
150	  /// Code Map) and makes it active, handing [ChatReady.restoreScrollOffset]
151	  /// whatever [recordScrollOffset] last captured for it (`null` if this
152	  /// session was never scrolled in this app run — `ChatScreen`'s own cue
153	  /// to jump to the bottom instead). A no-op while bootstrap hasn't
154	  /// resolved yet, same guard shape as [sendMessage].
155	  Future<Either<Failure, Unit>> switchSession(String sessionId) async {
156	    final current = state;
157	    if (current is! ChatReady) {
158	      return right(unit);
159	    }
160	    if (sessionId == current.sessionId) {
161	      return right(unit);
162	    }
163	    // Review finding: "Cross-session stream leakage" — an AI response
164	    // still streaming into the *old* session must never be left running
165	    // once we switch away from it; its orphaned subscription's
166	    // `onData`/`onDone` would otherwise go on to mutate whichever session
167	    // becomes active next.
168	    await _cancelInFlightSend();
169	    final messagesResult = await _repository.listMessages(sessionId);
170	    if (isClosed) {
171	      return right(unit);
172	    }
173	    return messagesResult.match((failure) => left(failure), (messages) {
174	      if (!isClosed) {
175	        emit(
176	          ChatReady(
177	            sessionId: sessionId,
178	            messages: messages.map(_fromDomain).toList(),
179	            sessions: current.sessions,
180	            restoreScrollOffset: _scrollOffsets[sessionId],
181	          ),
182	        );
183	      }
184	      return right(unit);
185	    });
186	  }
187	
188	  /// I/O matrix: "New session online"/"New session offline" — calls
189	  /// `createSession()` (reused as-is, Code Map; already blocked offline
190	  /// at the repository level, Boundaries). On any [Left] (including
191	  /// [Failure.networkOffline]), the current session is left completely
192	  /// untouched — no state is emitted at all, only the [Failure] is handed
193	  /// back for `AppDrawer` to surface as a transient `SnackBar`
194	  /// (Boundaries). On success, the new session opens empty and becomes
195	  /// active, prepended to [ChatReady.sessions].
196	  Future<Either<Failure, Unit>> startNewSession() async {
197	    final current = state;
198	    if (current is! ChatReady) {
199	      return right(unit);
200	    }
201	    // Review finding: "Cross-session stream leakage" — same rationale as
202	    // [switchSession]'s own cancellation above; a brand new session is
203	    // never the same session as [current], so this always needs to run
204	    // (unlike [switchSession], there's no same-session no-op branch to
205	    // skip it for).
206	    await _cancelInFlightSend();
207	    final result = await _repository.createSession();
208	    if (isClosed) {
209	      return right(unit);
210	    }
211	    return result.match((failure) => left(failure), (session) {
212	      if (!isClosed) {
213	        emit(
214	          ChatReady(
215	            sessionId: session.id,
216	            messages: const [],
217	            sessions: [session, ...current.sessions],
218	          ),
219	        );
220	      }
221	      return right(unit);
222	    });
223	  }
