232	  /// Boundaries: optimistic user bubble, then subscribes to
233	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
234	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
235	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
236	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
237	  ///
238	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
239	  /// or failed — the composer is disabled in that case anyway), while
240	  /// [content] is blank once trimmed, or while [_isSending] is already
241	  /// true — this story never races two concurrent sends against the one
242	  /// in-memory session (Boundaries: no offline lock/composer-disable UI
243	  /// of its own exists yet, Story 6.3's job, so this guard is the one
244	  /// thing standing in for it here). Deliberately not keyed off any
245	  /// loaded message's persisted `streaming` status — a message restored
246	  /// from history/cache can legitimately carry that status without a
247	  /// send actually being in flight (I/O matrix: mid-stream drop).
248	  Future<void> sendMessage(String content) async {
249	    final trimmed = content.trim();
250	    if (trimmed.isEmpty) {
251	      return;
252	    }
253	    final current = state;
254	    if (current is! ChatReady) {
255	      return;
256	    }
257	    if (_isSending) {
258	      return;
259	    }
260	    _isSending = true;
261	
262	    final userMessage = ChatUiMessage(
263	      id: _nextLocalId(),
264	      role: ChatMessageRole.user,
265	      content: trimmed,
266	      status: ChatMessageStatus.complete,
267	    );
268	    final aiMessage = ChatUiMessage(
269	      id: _nextLocalId(),
270	      role: ChatMessageRole.assistant,
271	      content: '',
272	      status: ChatMessageStatus.streaming,
273	    );
274	    emit(
275	      current.copyWith(
276	        messages: [...current.messages, userMessage, aiMessage],
277	        isSending: true,
278	      ),
279	    );
280	
281	    await _sendSubscription?.cancel();
282	    final completer = Completer<void>();
283	    _sendCompleter = completer;
284	    _sendSubscription = _repository
285	        .sendMessage(current.sessionId, trimmed)
286	        .listen(
287	          (event) {
288	            event.match(
289	              (failure) => _markFailed(aiMessage.id),
290	              (streamEvent) => _applyStreamEvent(aiMessage.id, streamEvent),
291	            );
292	          },
293	          onError: (Object _, StackTrace _) {
294	            // RNF09: no exception escapes the cubit — a stream-level
295	            // error (shouldn't happen, `ChatRemoteDataSource.sendMessage`
296	            // never lets one through unmapped) still only fails the
297	            // bubble, never crashes.
