319	  /// an in-band error, or a stream-level error) — the single place both
320	  /// flip back together.
321	  void _finishSending() {
322	    _isSending = false;
323	    if (isClosed) {
324	      return;
325	    }
326	    final current = state;
327	    if (current is ChatReady) {
328	      emit(current.copyWith(isSending: false));
329	    }
330	  }
