332	  void _applyStreamEvent(String aiMessageId, ChatStreamEvent event) {
333	    if (isClosed) {
334	      return;
335	    }
336	    final current = state;
337	    if (current is! ChatReady) {
338	      return;
339	    }
340	    switch (event) {
341	      case ChatMessageCreatedEvent():
342	        // Design Notes: the persisted *user*-message id — no UI-facing
