367	            ],
368	          ),
369	        );
370	    }
371	  }
372	
373	  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
374	  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
375	  /// as-is (never cleared, Boundaries).
376	  void _markFailed(String aiMessageId) {
377	    if (isClosed) {
378	      return;
379	    }
380	    final current = state;
381	    if (current is! ChatReady) {
382	      return;
383	    }
384	    emit(
385	      current.copyWith(
386	        messages: [
387	          for (final message in current.messages)
388	            if (message.id == aiMessageId)
389	              message.copyWith(status: ChatMessageStatus.failed)
390	            else
391	              message,
392	        ],
393	      ),
394	    );
395	  }
