404	  /// below (cancel the subscription, resolve the stranded [sendMessage]
405	  /// caller, clear the re-entrancy guard), just without closing the cubit
406	  /// itself — a no-op when nothing is actually in flight.
407	  Future<void> _cancelInFlightSend() async {
408	    if (!_isSending) {
409	      return;
410	    }
411	    await _sendSubscription?.cancel();
412	    _sendSubscription = null;
413	    final completer = _sendCompleter;
414	    if (completer != null && !completer.isCompleted) {
